class Solution:
    def validPath(self, n, edges, s, d):
        graph = {i: [] for i in range(n)}

        for edge in edges:
            v1, v2 = edge
            graph[v1].append(v2)
            graph[v2].append(v1)

        visited = set()
        queue = deque([s])

        while queue:
            current = queue.popleft()

            if current == d:
                return True

            visited.add(current)

            for neighbor in graph[current]:
                if neighbor not in visited:
                    queue.append(neighbor)
                    visited.add(neighbor)  # Mark the neighbor as visited to avoid revisiting

        return False

