    def findCircleNum(self, isConnected: List[List[int]]) -> int:

        numCities = len(isConnected)
        # 0 mean not visited
        cities = [0] * numCities
        count = 0
        q = collections.deque()

        for c in range(numCities):
            if cities[c] == 0:
                count += 1
                q.append(c)
                while q:
                    candidate = q.popleft()
                    cities[candidate] = 1
                    for i in range(numCities):
